class _AsyncScriptVersions:
    def __init__(self, client: "AsyncClient") -> None:
        self._client = client

    async def create(self, slug: Union[str, int], *, archive: str, command: str = NOT_GIVEN, build: Optional[str] = NOT_GIVEN, input_schema: Dict[str, Any] = NOT_GIVEN, output_schema: Optional[Dict[str, Any]] = NOT_GIVEN, hosts: List[str] = NOT_GIVEN, secrets: Dict[str, Dict[str, Any]] = NOT_GIVEN, env: List[str] = NOT_GIVEN, timeout: int = NOT_GIVEN, readme: Optional[str] = NOT_GIVEN, tags: List[str] = NOT_GIVEN, via: Literal["cli", "api", "app"] = NOT_GIVEN, request_options: Optional[RequestOptions] = None) -> "ScriptVersion":
        """Upload a version

        Uploads a new DRAFT version: the script's folder (a .tar.gz, base64 — the CLI makes it), the command that runs it and the JSON Schema of its inputs. Leave the command out and it is worked out from the folder: pyproject.toml's one script, package.json's bin, start or main, or the folder's one .py, .js, .ts or .sh file; leave the schema out and each `{name}` in the command is a text input. Its dependencies (requirements.txt, pyproject.toml, package.json) are installed now, once; a failed install answers 400 with what it printed. Runs keep using the published version until this one is published."""
        return await self._client._call(
            {"method": "post", "path": "/scripts/{slug}/versions", "query": [], "body": True, "names": {"command": "command", "build": "build", "input_schema": "inputSchema", "output_schema": "outputSchema", "archive": "archive", "hosts": "hosts", "secrets": "secrets", "env": "env", "timeout": "timeout", "readme": "readme", "tags": "tags", "via": "via"}},
            {"slug": slug},
            {"command": command, "build": build, "input_schema": input_schema, "output_schema": output_schema, "archive": archive, "hosts": hosts, "secrets": secrets, "env": env, "timeout": timeout, "readme": readme, "tags": tags, "via": via},
            request_options,
        )

    async def list(self, slug: Union[str, int], *, request_options: Optional[RequestOptions] = None) -> Dict[str, Any]:
        """List a script's versions

        Every version, newest first, and which one is published."""
        return await self._client._call(
            {"method": "get", "path": "/scripts/{slug}/versions", "query": [], "body": False, "names": {}},
            {"slug": slug},
            {},
            request_options,
        )

    async def publish(self, slug: Union[str, int], number: Union[str, int], *, request_options: Optional[RequestOptions] = None) -> Union["Script", "PublishRequested"]:
        """Publish a version

        Makes this version the one every run uses — from the app, the API, agents and schedules. Publishing an older version again rolls back. The script's owner, or a workspace owner or admin. An agent's publish (and anyone's, when the workspace requires a second person) becomes a request a person approves — answered 202."""
        return await self._client._call(
            {"method": "post", "path": "/scripts/{slug}/versions/{number}/publish", "query": [], "body": False, "names": {}},
            {"slug": slug, "number": number},
            {},
            request_options,
        )

    async def run(self, slug: Union[str, int], number: Union[str, int], *, inputs: Dict[str, Any] = NOT_GIVEN, via: Literal["api", "cli"] = NOT_GIVEN, request_options: Optional[RequestOptions] = None) -> Union["Run", "HeldRun"]:
        """Test-run a version

        Runs one VERSION — a draft before publishing — with these inputs, as a test run: recorded with `test: true`, not counted as the script's use, and without run events (no webhooks, no triggers). For the version's uploader, the script's owner, or an owner or admin; the script's approval policy still applies. Prove a draft works before asking a person to publish it."""
        return await self._client._call(
            {"method": "post", "path": "/scripts/{slug}/versions/{number}/runs", "query": [], "body": True, "names": {"inputs": "inputs", "via": "via"}},
            {"slug": slug, "number": number},
            {"inputs": inputs, "via": via},
            request_options,
        )


class _AsyncSecrets:
    def __init__(self, client: "AsyncClient") -> None:
        self._client = client

    async def delete(self, name: Union[str, int], *, request_options: Optional[RequestOptions] = None) -> None:
        """Delete a secret

        Deletes it and its value in every environment; runs of scripts that use it fail until it is saved again. Workspace owners and admins, or a workspace API key."""
        return await self._client._call(
            {"method": "delete", "path": "/secrets/{name}", "query": [], "body": False, "names": {}},
            {"name": name},
            {},
            request_options,
        )

    async def list(self, *, request_options: Optional[RequestOptions] = None) -> Dict[str, Any]:
        """List secrets

        The workspace's secrets by name, with the environments that have a value and the hosts each value may be sent to — never the values."""
        return await self._client._call(
            {"method": "get", "path": "/secrets", "query": [], "body": False, "names": {}},
            {},
            {},
            request_options,
        )

    async def set(self, name: Union[str, int], *, value: str, hosts: List[str], allow_env: bool = NOT_GIVEN, request_options: Optional[RequestOptions] = None) -> "Secret":
        """Save a secret

        Saves the secret's value in the request's environment: creates it, or replaces the value and its hosts (rotation). The value is encrypted and never returned by any call. `hosts` are the ONLY hosts that value is ever sent to — a script cannot send it anywhere else. Workspace owners and admins, or a workspace API key."""
        return await self._client._call(
            {"method": "put", "path": "/secrets/{name}", "query": [], "body": True, "names": {"value": "value", "hosts": "hosts", "allow_env": "allowEnv"}},
            {"name": name},
            {"value": value, "hosts": hosts, "allow_env": allow_env},
            request_options,
        )

    async def unset(self, name: Union[str, int], environment: Union[str, int], *, request_options: Optional[RequestOptions] = None) -> None:
        """Remove a secret's value from an environment

        Removes the value in that environment only; the secret and its other values stay. Runs there that use it fail until a value is saved again. Workspace owners and admins, or a workspace API key."""
        return await self._client._call(
            {"method": "delete", "path": "/secrets/{name}/values/{environment}", "query": [], "body": False, "names": {}},
            {"name": name, "environment": environment},
            {},
            request_options,
        )


